text:
Use `pg` pool. Key config:

```js
import { Pool } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Pool sizing
  max: 20,          // max connections (default 10)
  min: 2,           // keep alive when idle
  idleTimeoutMillis: 30_000,    // kill idle conn after 30s
  connectionTimeoutMillis: 5_000, // fail fast if can't connect in 5s

  // Optional: SSL in prod
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// Catch pool-level errors (e.g. DB restart)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});
```

**Query wrapper with error handling:**

```js
export async function query(sql, params) {
  const start = Date.now();
  try {
    const res = await pool.query(sql, params);
    console.debug(`Query took ${Date.now() - start}ms, rows: ${res.rowCount}`);
    return res;
  } catch (err) {
    console.error('Query failed:', { sql, params, err: err.message });
    throw err;  // let caller handle
  }
}
```

**Transaction wrapper:**

```js
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();  // ALWAYS release, even on error
  }
}
```

**Usage:**

```js
// Simple query
const { rows } = await query('SELECT * FROM users WHERE id = $1', [userId]);

// Transaction
await withTransaction(async (client) => {
  await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, fromId]);
  await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, toId]);
});
```

**Key points:**

| Thing | Why |
|-------|-----|
| `max: 20` | Match DB `max_connections` minus headroom for admin |
| `connectionTimeoutMillis` | Prevent request hang when pool exhausted |
| `idleTimeoutMillis` | Avoid stale conn on DB-side timeout |
| `pool.on('error')` | Without this, idle client error = unhandled exception = crash |
| `client.release()` in `finally` | Leak conn = pool exhaustion = app freeze |

**Graceful shutdown:**

```js
process.on('SIGTERM', async () => {
  await pool.end();  // drain active queries, then close
  process.exit(0);
});
```
